SELECT equipmentcode, performanceindex, reliabilityindex, environmentalimpactindex, 
       ROUND(CAST((performanceindex + reliabilityindex) / 2.0 * (1.0 - environmentalimpactindex / 10.0) AS numeric), 2) AS eer
FROM equipment ORDER BY equipmentcode LIMIT 5;

SELECT COUNT(*) AS total, COUNT(DISTINCT eer) AS distinct_eer FROM (
    SELECT ROUND(CAST((performanceindex + reliabilityindex) / 2.0 * (1.0 - environmentalimpactindex / 10.0) AS numeric), 2) AS eer FROM equipment
) t;

SELECT equipmentcode, 
       ROUND(CAST((performanceindex + reliabilityindex) / 2.0 AS numeric), 2) AS avg_pr
FROM equipment ORDER BY equipmentcode LIMIT 5;

SELECT equipmentcode, performanceindex, reliabilityindex, environmentalimpactindex,
       ROUND(CAST((performanceindex + reliabilityindex) / 2.0 * (1.0 - environmentalimpactindex) / 10.0 AS numeric), 2) AS eer_alt
FROM equipment ORDER BY equipmentcode LIMIT 5;

SELECT equipmentcode, efficiencyindex, 
       ROUND(CAST((efficiencyindex) * (1.0 - environmentalimpactindex / 10.0) AS numeric), 2) AS eer_alt
FROM equipment ORDER BY equipmentcode LIMIT 5;

SELECT equipmentcode, 
       ROUND(CAST(performanceindex AS numeric) + CAST(reliabilityindex AS numeric) / 2.0 * (1.0 - CAST(environmentalimpactindex AS numeric) / 10.0), 2) AS eer_alt
FROM equipment ORDER BY equipmentcode LIMIT 5;

SELECT equipmentcode, 
       ROUND(CAST((CAST(performanceindex AS numeric) + CAST(reliabilityindex AS numeric)) / 2.0 * (1.0 - CAST(environmentalimpactindex AS numeric) / 10.0) AS numeric), 2) AS eer
FROM equipment ORDER BY equipmentcode LIMIT 5;
